      {
        "name": "Lash",
        "description": "The aboleth makes one Tentacle attack."
      },
      {
        "name": "Psychic Drain",
        "description": "If the aboleth has at least one creature Charmed or Grappled, it uses Consume Memories and regains 5 (1d10) Hit Points."
      }
